{"content":"//! Three concrete stores, with quite different internals.

#[path = "store.rs"]
pub mod store;

use std::collections::HashMap;
use store::Store;

/// A plain hash map. Nothing is ever dropped.
pub struct MemStore {
    map: HashMap<String, String>,
}

impl MemStore {
    pub fn new() -> Self {
        MemStore { map: HashMap::new() }
    }
}

impl Store for MemStore {
    fn name(&self) -> &'static str {
        "mem"
    }

    fn get(&self, key: &str) -> Option<String> {
        self.map.get(key).cloned()
    }

    fn put(&mut self, key: &str, value: &str) {
        self.map.insert(key.to_string(), value.to_string());
    }

    fn evict(&mut self, key: &str) -> bool {
        self.map.remove(key).is_some()
    }

    fn len(&self) -> usize {
        self.map.len()
    }
}

/// A fixed-capacity ring. The oldest insertion is overwritten when it is full,
/// so entries live in insertion order in a Vec.
pub struct RingStore {
    slots: Vec<(String, String)>,
    cap: usize,
    next: usize,
}

impl RingStore {
    pub fn with_capacity(cap: usize) -> Self {
        RingStore { slots: Vec::new(), cap, next: 0 }
    }
}

impl Store for RingStore {
    fn name(&self) -> &'static str {
        "ring"
    }

